import json


def extract_json(text, kind=None):
    starts = {"object": "{", "array": "["}
    if kind is None:
        wanted = "{["
    elif kind in starts:
        wanted = starts[kind]
    else:
        raise ValueError("kind must be None, 'object' or 'array'")
    decoder = json.JSONDecoder()
    for position, char in enumerate(text):
        if char not in wanted:
            continue
        try:
            value, _ = decoder.raw_decode(text, position)      # parses one value starting exactly here
        except ValueError:
            continue                                           # not JSON from this brace: try the next one
        return value
    return None
